func insertLocalizationByIndex(locText string, ref *insertIndexRef, entries []locEntry) string {
	if len(entries) == 0 {
		return locText
	}
	if ref == nil {
		return locText
	}
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	bodyStart := m[2]
	bodyEnd := m[3]
	lines := strings.Split(body, "\n")
	insertLines := make([]string, len(entries))
	for i, e := range entries {
		insertLines[i] = fmt.Sprintf(`        "%s" "%s"`, e.key, e.value)
	}
	idx := ref.Value
	if idx < 0 {
		idx = 0
	}
	if idx > len(lines) {
		idx = len(lines)
	}
	newLines := append([]string{}, lines[:idx]...)
	newLines = append(newLines, insertLines...)
	newLines = append(newLines, lines[idx:]...)
	ref.Value += len(insertLines)
	newBody := strings.Join(newLines, "\n")
	return locText[:bodyStart] + newBody + locText[bodyEnd:]
}

func deriveInsertRef(locText, itemName string, global *insertIndexRef) *insertIndexRef {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return &insertIndexRef{Value: 0}
	}
	body := locText[m[2]:m[3]]
	lines := strings.Split(body, "\n")
	prefix := fmt.Sprintf(`"%s`, fmt.Sprintf("DOTA_Tooltip_Ability_%s_", itemName))

	lastIdx := -1
	for i, line := range lines {
		if strings.Contains(line, prefix) {
			lastIdx = i
		}
	}

	if lastIdx >= 0 {
		return &insertIndexRef{Value: lastIdx + 1}
	}
	if global != nil {
		return &insertIndexRef{Value: global.Value}
	}
	return &insertIndexRef{Value: len(lines)}
}

