// ---------- bonus attribute order ----------

func getBonusAttributeOrder(tokens []kv.Token, itemName string) []string {
	order := []string{}
	i := 0
	for i < len(tokens) {
		tk := tokens[i]
		if tk.Typ == "str" && tk.Val == itemName {
			if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
				i += 2
				depth := 1
				for i < len(tokens) && depth > 0 {
					cur := tokens[i]
					if cur.Typ == "{" {
						depth++
						i++
						continue
					}
					if cur.Typ == "}" {
						depth--
						i++
						continue
					}
					if depth == 1 && cur.Typ == "str" && cur.Val == "BonusAttribute" {
						if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
							i += 2
							bDepth := 1
							for i < len(tokens) && bDepth > 0 {
								bt := tokens[i]
								if bt.Typ == "{" {
									bDepth++
									i++
									continue
								}
								if bt.Typ == "}" {
									bDepth--
									i++
									continue
								}
								if bDepth == 1 && bt.Typ == "str" {
									if i+1 < len(tokens) && tokens[i+1].Typ == "str" {
										order = append(order, bt.Val)
										i += 2
										continue
									}
								}
								i++
							}
							return order
						}
					}
					i++
				}
				break
			}
		}
		i++
	}
	return order
}

// ---------- auto cast dummies ----------

func ensureAutoCastDummies(resolve func(string) string, resolveForWrite func(string) string, heroMax map[string]int) error {
	if len(heroMax) == 0 {
		fmt.Println("[auto-dummy] skip: no heroes with max level info")
		return nil
	}

	dummyPath := resolveForWrite(filepath.Join("game/dzsj/scripts/npc/units", "npc_dota_auto_cast_dummy.txt"))
	dummyText, err := kv.ReadFileIfExists(dummyPath)
	if err != nil || strings.TrimSpace(dummyText) == "" {
		return fmt.Errorf("dummy file missing or empty: %s", dummyPath)
	}

	heroesPath := resolve(filepath.Join("game/dzsj/excel/Dota2 原版游戏配置", "npc_heroes.txt"))
	heroesText, err := kv.ReadFileIfExists(heroesPath)
	if err != nil || strings.TrimSpace(heroesText) == "" {
		return fmt.Errorf("read heroes text: %w", err)
	}
	heroesCustomPath := resolve(filepath.Join("game/dzsj/scripts/npc", "npc_heroes_custom.txt"))
	heroesCustomText, _ := kv.ReadFileIfExists(heroesCustomPath)

	defaultWearPath := resolve(filepath.Join("game/dzsj/scripts/npc/utils", "default.txt"))
	defaultText, err := kv.ReadFileIfExists(defaultWearPath)
	if err != nil || strings.TrimSpace(defaultText) == "" {
		return fmt.Errorf("read default wearables: %w", err)
	}

	fmt.Printf("[auto-dummy] heroes to check: %v\n", heroMax)

	var newBlocks []string

	maxNeed := 0
	for _, lvl := range heroMax {
		if lvl > maxNeed {
			maxNeed = lvl
		}
	}
	if maxNeed < 1 {
		maxNeed = 1
	}

	templateBlocks := map[int]string{}
	for lvl := 1; lvl <= maxNeed; lvl++ {
		key := fmt.Sprintf("npc_dota_auto_cast_dummy_drow_ranger_%d", lvl)
		if blkText, ok := extractKVBlock(dummyText, key); ok {
			templateBlocks[lvl] = blkText
		}
	}
	if len(templateBlocks) == 0 {
		return fmt.Errorf("missing drow ranger template in dummy file")
	}
	templateLevels := getSortedKeys(templateBlocks)
	highestTpl := templateLevels[len(templateLevels)-1]

	for hero, maxLvl := range heroMax {
		key1 := fmt.Sprintf("npc_dota_auto_cast_dummy_%s_1", hero)
		if strings.Contains(dummyText, fmt.Sprintf("\"%s\"", key1)) {
			fmt.Printf("[auto-dummy] exists, skip %s\n", key1)
			continue
		}

		heroKey := "npc_dota_hero_" + hero
		heroBlk, ok := extractKVBlock(heroesText, heroKey)
		if !ok && strings.TrimSpace(heroesCustomText) != "" {
			heroBlk, ok = extractKVBlock(heroesCustomText, heroKey)
		}
		if !ok {
			fmt.Printf("[auto-dummy] hero block not found for %s\n", heroKey)
			continue
		}
		heroObj, err := parseSingleBlock(heroBlk)
		if err != nil {
			fmt.Printf("[auto-dummy] parse hero block failed for %s: %v\n", heroKey, err)
			continue
		}
		model, ok := heroObj.GetString("Model")
		if !ok || strings.TrimSpace(model) == "" {
			fmt.Printf("[auto-dummy] model missing for %s\n", heroKey)
			continue
		}

		wearBlk, _ := extractKVBlock(defaultText, heroKey)
		wearObj, _ := parseSingleBlock(wearBlk)
		wearKeys := []string{}
		if wearObj != nil {
			wearKeys = append(wearKeys, wearObj.Keys...)
		} else {
			fmt.Printf("[auto-dummy] wearables missing for %s\n", heroKey)
		}

		if maxLvl < 1 {
			maxLvl = 1
		}

		for lvl := 1; lvl <= maxLvl; lvl++ {
			srcLvl := lvl
			if _, ok := templateBlocks[srcLvl]; !ok {
				srcLvl = highestTpl
			}
			templateRaw := templateBlocks[srcLvl]
			blockKey := fmt.Sprintf("npc_dota_auto_cast_dummy_%s_%d", hero, lvl)
			blockText := renderDummyBlock(templateRaw, blockKey, model, wearKeys)
			newBlocks = append(newBlocks, blockText)
			fmt.Printf("[auto-dummy] prepared %s (tpl %d)\n", blockKey, srcLvl)
		}
	}

	if len(newBlocks) == 0 {
		fmt.Println("[auto-dummy] no new dummy blocks generated")
		return nil
	}

	var builder strings.Builder
	builder.WriteString(dummyText)
	if !strings.HasSuffix(dummyText, "\n") {
		builder.WriteString("\n")
	}
	for _, b := range newBlocks {
		builder.WriteString("\n")
		builder.WriteString(b)
	}

	if err := os.WriteFile(dummyPath, []byte(builder.String()), 0o644); err != nil {
		return fmt.Errorf("write dummy file: %w", err)
	}

	fmt.Printf("[auto-dummy] appended %d dummy blocks to %s\n", len(newBlocks), dummyPath)
	return nil
}

func getSortedKeys[T any](m map[int]T) []int {
	keys := make([]int, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Ints(keys)
	return keys
}

func renderKVBlock(key string, obj *kv.KVObject) string {
	return fmt.Sprintf("\"%s\"\n{\n%s}\n", key, kvToString(obj, 1))
}

func kvToString(obj *kv.KVObject, indent int) string {
	pad := strings.Repeat("\t", indent)
	var b strings.Builder
	for _, k := range obj.Keys {
		v := obj.Values[k]
		switch vv := v.(type) {
		case string:
			b.WriteString(fmt.Sprintf("%s\"%s\"\t\t\"%s\"\n", pad, k, vv))
		case *kv.KVObject:
			b.WriteString(fmt.Sprintf("%s\"%s\"\n", pad, k))
			b.WriteString(fmt.Sprintf("%s{\n", pad))
			b.WriteString(kvToString(vv, indent+1))
			b.WriteString(fmt.Sprintf("%s}\n", pad))
		}
	}
	return b.String()
}

// renderDummyBlock replaces key/Model/AttachWearables using raw template text (tolerant to non-standard formatting).
func renderDummyBlock(templateRaw, newKey, model string, wearKeys []string) string {
	out := templateRaw

	reKey := regexp.MustCompile(`"npc_dota_auto_cast_dummy_drow_ranger_\d+"`)
	out = reKey.ReplaceAllString(out, fmt.Sprintf("\"%s\"", newKey))

	reModel := regexp.MustCompile(`"Model"\s*"[^"]*"`)
	out = reModel.ReplaceAllString(out, fmt.Sprintf("\"Model\"\t\t\"%s\"", model))

	var attachBuilder strings.Builder
	attachBuilder.WriteString("\t\t\"AttachWearables\"\n\t\t{\n")
	for i, id := range wearKeys {
		attachBuilder.WriteString(fmt.Sprintf("\t\t      \"Wearable%d\"\t\t{	\"ItemDef\"\t\t\"%s\"\t\t}\n", i+1, id))
	}
	attachBuilder.WriteString("\t\t}")
	attachBlock := attachBuilder.String()

	reAttach := regexp.MustCompile(`"AttachWearables"\s*\{[\s\S]*?\}`)
	if reAttach.MatchString(out) {
		out = reAttach.ReplaceAllString(out, attachBlock)
	} else {
		reCreature := regexp.MustCompile(`"Creature"\s*\{`)
		loc := reCreature.FindStringIndex(out)
		if loc != nil {
			insertPos := loc[1]
			out = out[:insertPos] + "\n" + attachBlock + out[insertPos:]
		} else {
			// fallback append at end
			out = out + "\n" + attachBlock + "\n"
		}
	}

	return out
}

// extract a KV block text by key using brace matching (ignores parse errors elsewhere)
func extractKVBlock(text, key string) (string, bool) {
	keyQuoted := fmt.Sprintf("\"%s\"", key)
	idx := strings.Index(text, keyQuoted)
	if idx < 0 {
		return "", false
	}
	braceStart := strings.Index(text[idx:], "{")
	if braceStart < 0 {
		return "", false
	}
	start := idx + braceStart
	depth := 0
	inStr := false
	escape := false
	for i := start; i < len(text); i++ {
		ch := text[i]
		if inStr {
			if escape {
				escape = false
				continue
			}
			if ch == '\\' {
				escape = true
				continue
			}
			if ch == '"' {
				inStr = false
			}
			continue
		}
		if ch == '"' {
			inStr = true
			continue
		}
		if ch == '{' {
			depth++
			continue
		}
		if ch == '}' {
			depth--
			if depth == 0 {
				end := i + 1
				return text[idx:end], true
			}
			continue
		}
	}
	return "", false
}

func parseSingleBlock(block string) (*kv.KVObject, error) {
	wrapped := fmt.Sprintf("root\n{\n%s\n}\n", block)
	toks := kv.TokenizeKV(wrapped)
	obj, err := kv.ParseKV(toks)
	if err != nil {
